# Break My Fix finding 3, generated by Tracefix: Env.db_url_config returns a wrong value.
# Property (docstring): Every entry of a non-empty extra_options dict appears in the result's OPTIONS with the same value, for every recognised database URL, including sqlite in-memory URLs.
# Quote: Optional dictionary merged into ``OPTIONS`` after URL parsing.
# Run it with pytest: it fails for as long as the code breaks this property.

from environ.environ import Env


def test_break_my_fix_3() -> None:
    url = 'sqlite://:memory:'
    extra_options = {'timeout': 20}
    # The property applies to this input: isinstance(extra_options, dict) and len(extra_options) > 0 and isinstance(url, str) and url.split('://')[0] in Env.DB_SCHEMES
    result = Env.db_url_config(url=url, extra_options={'timeout': 20})
    assert (isinstance(result.get('OPTIONS'), dict) and all(k in result['OPTIONS'] and result['OPTIONS'][k] == v for k, v in extra_options.items()))
